var DATA = {"failure": "Crash with uncommitted writes in WAL", "steps": "Read last checkpoint|Replay WAL forward|Redo committed|Undo uncommitted", "guarantee": "Atomicity + durability", "log": "BEGIN T1|WRITE T1 a=1|COMMIT T1|BEGIN T2|WRITE T2 b=2"};
console.log("Failure point: " + DATA.failure);
console.log("Guarantees: " + DATA.guarantee);
var entries = DATA.log.split("|").map(function (s) { return s.trim(); });
var committed = [], active = null;
console.log("--- WAL replay ---");
entries.forEach(function (e) {
  var m = e.match(/(BEGIN|COMMIT|ABORT|WRITE)\s*(T\d+)?\s*(.*)/i);
  if (!m) { console.log("  ? " + e); return; }
  var op = m[1].toUpperCase(), tx = m[2] || "", rest = m[3] || "";
  if (op === "BEGIN") { active = tx; console.log("  BEGIN " + tx); }
  else if (op === "COMMIT") { committed.push(tx); console.log("  COMMIT " + tx + " -> durable"); active = null; }
  else if (op === "ABORT") { console.log("  ABORT " + tx + " -> rolled back"); active = null; }
  else if (op === "WRITE") { console.log("  WRITE " + tx + " " + rest + (committed.indexOf(tx) >= 0 ? "" : " (uncommitted)")); }
});
console.log("--- recovery steps ---");
DATA.steps.split("|").forEach(function (s, i) { console.log("  " + (i + 1) + ". " + s.trim()); });
console.log("RESULT: replay complete — committed=" + committed.join(",") + "; uncommitted rolled back.");

